  const nfkd = text.normalize('NFKD');
  let out = '';
  for (const ch of nfkd) {
    const cp = ch.codePointAt(0);
    if (cp > 127) continue;
    if (isAlnumUnderscore(ch) || ch === '-' || isSpace(ch)) out += ch;
  }
  out = out.trim().toLowerCase();
  // fold runs of [-\s] into '-'
  let folded = '';
  let i = 0;
  while (i < out.length) {
    const ch = out[i];
    if (ch === '-' || isSpace(ch)) {
      // consume run
