// toc.mjs — TOC (table of contents) support mirroring Python-Markdown's
// `toc` extension. Zero dependencies, ESM, no regular expressions
// (all matching is done with explicit character scanning).
//
// Exports and contract:
//   - createTocState(): returns the per-document toc state (stored at
//     state.toc of the shared document state):
//       { headings: Array<{ level:number, id:string, textHtml:string }>,
//         used: Set<string> }
//   - registerHeading(tocState, level, rawInline): records a heading and
//     returns its unique id (to be placed on the rendered <hN> tag).
//   - renderToc(tocState): renders the <div class="toc"> block. Output never
//     ends with a newline.
//   - isTocMarkerText(text): true only for exactly "[TOC]" (strictly
//     uppercase; callers may trim before calling).
//
// Dependency on inline.mjs (implemented by another module):
//   plainTextForInline(rawInline, mode)
//     - mode 'plain' -> entity-decoded plain text of the heading (slug source)
//     - mode 'toc'   -> HTML-escaped plain text for the TOC link body
//   Both call sites are isolated in headingPlainText()/headingTocHtml()
//   below so the integration can adjust the signature in one place if the
//   final inline.mjs contract differs.

import { plainTextForInline } from './inline.mjs';

// ---------------------------------------------------------------------------
// inline.mjs adapters
// ---------------------------------------------------------------------------

function headingPlainText(rawInline) {
  const value = plainTextForInline(rawInline, 'plain');
  return typeof value === 'string' ? value : String(value ?? '');
}

function headingTocHtml(rawInline) {
  const value = plainTextForInline(rawInline, 'toc');
  return typeof value === 'string' ? value : String(value ?? '');
}

// ---------------------------------------------------------------------------
// Character classification helpers (no regex)
// ---------------------------------------------------------------------------

function isSpaceChar(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' ||
         ch === '\r' || ch === '\x0b' || ch === '\f';
}

function isAsciiWordChar(ch) {
  return (ch >= 'a' && ch <= 'z') ||
         (ch >= 'A' && ch <= 'Z') ||
         (ch >= '0' && ch <= '9') ||
         ch === '_';
}

function isDigitChar(ch) {
  return ch >= '0' && ch <= '9';
}

// ---------------------------------------------------------------------------
// slugify — mirrors markdown.extensions.toc.slugify with separator '-':
//   NFKD normalize, drop non-ASCII, drop chars outside [A-Za-z0-9_ \s-],
//   strip, lowercase, then fold every run of [-\s] into a single '-'.
// ---------------------------------------------------------------------------

export function slugify(text) {
  const normalized = String(text).normalize('NFKD');

  // Keep ASCII word chars, ASCII whitespace and '-'; drop everything else.
  let kept = '';
  for (const ch of normalized) {
    if (ch.codePointAt(0) > 127) continue;
    if (isAsciiWordChar(ch) || isSpaceChar(ch) || ch === '-') kept += ch;
  }

  const lowered = kept.trim().toLowerCase();

  // Fold consecutive '-' / whitespace runs into a single '-'.
  let out = '';
  let i = 0;
  while (i < lowered.length) {
    const ch = lowered[i];
    if (ch === '-' || isSpaceChar(ch)) {
      while (i < lowered.length &&
             (lowered[i] === '-' || isSpaceChar(lowered[i]))) {
        i += 1;
      }
      out += '-';
    } else {
      out += ch;
      i += 1;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// unique id — mirrors markdown.extensions.toc.unique: while the id is empty
// or already used, increment a trailing "_<number>" suffix if present,
// otherwise append "_1". Scans from the end instead of a regex.
// ---------------------------------------------------------------------------

function matchTrailingCount(id) {
  let end = id.length;
  while (end > 0 && isDigitChar(id[end - 1])) end -= 1;
  if (end === id.length) return null;      // no trailing digits
  if (end === 0 || id[end - 1] !== '_') return null; // digits not after '_'
  let num = 0;
  for (let i = end; i < id.length; i += 1) {
    num = num * 10 + (id.charCodeAt(i) - 48);
  }
  return { base: id.slice(0, end - 1), num };
}

function uniqueId(slug, used) {
  let id = slug;
  while (id.length === 0 || used.has(id)) {
    const m = matchTrailingCount(id);
    id = m ? m.base + '_' + String(m.num + 1) : id + '_1';
  }
  used.add(id);
  return id;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function createTocState() {
  return { headings: [], used: new Set() };
}

export function registerHeading(state, level, rawInline) {
  if (!state.used) state.used = new Set();
  if (!state.headings) state.headings = [];
  const plain = headingPlainText(rawInline);
  const textHtml = headingTocHtml(rawInline);
  const id = uniqueId(slugify(plain), state.used);
  state.headings.push({ level, id, textHtml });
  return id;
}

export function isTocMarkerText(text) {
  return text === '[TOC]';
}

// ---------------------------------------------------------------------------
// renderToc — nesting rule: a heading deeper than the previous one becomes
// its child; before placing a heading, pop every open item whose level is
// >= the current level. Serialized without indentation; a child <ul> sits
// on the same line directly after its parent's </a>.
// ---------------------------------------------------------------------------

function buildTree(headings) {
  const root = { children: [] };
  const stack = [{ level: 0, node: root }];
  for (const h of headings) {
    const node = { level: h.level, id: h.id, textHtml: h.textHtml, children: [] };
    while (stack.length > 1 && stack[stack.length - 1].level >= h.level) {
      stack.pop();
    }
    stack[stack.length - 1].node.children.push(node);
    stack.push({ level: h.level, node });
  }
  return root.children;
}

function serializeUl(children) {
  let s = '<ul>\n';
  for (const c of children) {
    s += '<li><a href="#' + c.id + '">' + c.textHtml + '</a>';
    if (c.children.length > 0) s += serializeUl(c.children) + '\n';
    s += '</li>\n';
  }
  s += '</ul>';
  return s;
}

export function renderToc(state) {
  const headings = (state && state.headings) || [];
  if (headings.length === 0) {
    return '<div class="toc">\n<ul></ul>\n</div>';
  }
  return '<div class="toc">\n' + serializeUl(buildTree(headings)) + '\n</div>';
}

